-- Estructura de tabla para la tabla `transaccion_historica_02`
--

DROP TABLE IF EXISTS `transaccion_historica_02`;
CREATE TABLE `transaccion_historica_02` (
  `ID` int(11) NOT NULL,
  `FechaVenta` date DEFAULT NULL,
  `Titulo` varchar(20) DEFAULT NULL,
  `Titular` varchar(20) DEFAULT NULL,
  `FechaCompra` date DEFAULT NULL,
  `FechaPrimerPago` date DEFAULT NULL,
  `FechaEmision` date DEFAULT NULL,
  `FechaVencimiento` date DEFAULT NULL,
  `TasaMensual` decimal(18,2) DEFAULT NULL,
  `TasaMensualReal` decimal(18,2) DEFAULT NULL,
  `Rendimiento` decimal(18,2) DEFAULT NULL,
  `InteresMensual` decimal(18,2) DEFAULT NULL,
  `InteresPrimerMes` decimal(18,2) DEFAULT NULL,
  `PeriodosRecibidos` int(11) DEFAULT NULL,
